cleanup() {
  const now = Date.now();
  const maxAge = 5 * 60 * 1000; // 5 minutes in milliseconds
  for (const key in this.storage) {
    if (now - this.storage[key].timestamp > maxAge) {
      delete this.storage[key];
    }
  }
}

